<?php
namespace ProjectPress\Includes\Project\Communication;use ProjectPress\Includes\Functions\Helpers\DBHelper;if(!defined('ABSPATH')){exit;}final class NotificationRepository{public function find(int$id):?Notification{$row=DBHelper::get_by_id('project_notifications',absint($id));return is_array($row)?new Notification($row):null;}public function for_project(int$id):array{return array_map(static fn(array$row):Notification=>new Notification($row),DBHelper::get_all('project_notifications',array('project_id'=>absint($id)),'*','created_at DESC'));}public function create(int$id,array$data){$record=DBHelper::insert('project_notifications',array_merge($data,array('project_id'=>absint($id),'created_by'=>get_current_user_id(),'created_at'=>current_time('mysql',true))));return false===$record?false:$this->find((int)$record);}public function delete(Notification$record):bool{return DBHelper::delete('project_notifications',array('id'=>$record->get_id(),'project_id'=>$record->get_project_id()));}}
